N=300; INSTANCES=30; density=0.01

def solve_ref(A):
    k=5;N=A.shape[0]
    v0=np.ones(N);
    return sla.eigs(A,k=k,v0=v0,maxiter=N*200,ncv=max(2*k+1,20))

def solve_fast(A):
